from pathlib import Path
from fractions import Fraction as Q
import ast,itertools as it,json,hashlib,resource,time,sys
sys.path.insert(0,'code')
from classification_cubic_scroll_abelian_review import add,scale,mul,diff,parse,determinant
begun=time.monotonic();resource.setrlimit(resource.RLIMIT_CPU,(170,175));resource.setrlimit(resource.RLIMIT_AS,(2048*1024**2,)*2)
jp=Path('research/classification/jobs/cubic_cone_rank_two_nodal_fisher_separate_review.json');job=json.loads(jp.read_text())
for v in job['exact_inputs_and_hashes']:assert hashlib.sha256(Path(v['path']).read_bytes()).hexdigest()==v['sha256'],v['path']
r=json.loads(Path('reports/CLASSIFICATION_CUBIC_CONE_RANK_TWO_NODAL_FISHER_ACTUAL_20261108.json').read_text())
old=json.loads(Path('reports/CLASSIFICATION_CUBIC_CONE_RANK_TWO_ONE_ORBIT_AMBIENT_20261108.json').read_text())
N=0
def ck(a,b,label):
 global N
 assert a==b,label
 N+=1
def one(n):return {(0,)*n:Q(1)}
def variable(n,i):a=[0]*n;a[i]=1;return {tuple(a):Q(1)}
def power(p,k,n):
 out=one(n)
 for _ in range(k):out=mul(out,p)
 return out
def subst(p,values,n):
 out={}
 for ex,c in p.items():
  term=scale(one(n),c)
  for i,k in enumerate(ex):
   if k:term=mul(term,power(values[i],k,n))
  out=add(out,term)
 return out
def neg(p):return scale(p,-1)
def specialize(p):return {ex:c for ex,c in p.items()if not ex[5]}
def inverse(A):
 n=len(A);a=[[Q(v)for v in row]+[Q(i==j)for j in range(n)]for i,row in enumerate(A)]
 for i in range(n):
  k=next(k for k in range(i,n)if a[k][i]);a[i],a[k]=a[k],a[i];c=a[i][i];a[i]=[v/c for v in a[i]]
  for j in range(n):
   if j!=i:
    c=a[j][i];a[j]=[v-c*w for v,w in zip(a[j],a[i])]
 return [row[n:]for row in a]
def mm(A,B):return [[sum(a*B[k][j]for k,a in enumerate(row))for j in range(len(B[0]))]for row in A]
def pdet(A):
 n=len(A);out={}
 for p in it.permutations(range(n)):
  term=one(6)
  for i,j in enumerate(p):term=mul(term,A[i][j])
  sign=(-1)**sum(p[i]>p[j]for i in range(n)for j in range(i+1,n));out=add(out,scale(term,sign))
 return out
pairs=list(it.combinations(range(5),2));triples=list(it.combinations(range(5),3));quads=list(it.combinations(range(5),4))
zn=[f'z{i}'for i in range(5)]+['e'];xn=[f'x{i}'for i in range(5)]+['e'];z=[variable(6,i)for i in range(6)];x=z
Phi=[[{}for _ in range(5)]for _ in range(5)]
literal=['-z3-e*z0','-z3','-z4','z2','z2','z3','-z1','-z1','z0','0']
for ij,text in zip(pairs,literal):
 i,j=ij;Phi[i][j]=parse(text,zn);Phi[j][i]=neg(Phi[i][j]);ck(Phi[i][j],parse(r['all10_model_entries'][str(ij)],zn),'literal Phi')
def pf4(P,omitted):
 a,b,c,d=[j for j in range(5)if j!=omitted]
 return scale(add(mul(P[a][b],P[c][d]),neg(mul(P[a][c],P[b][d])),mul(P[a][d],P[b][c])),(-1)**omitted)
pf=[pf4(Phi,i)for i in range(5)]
g=[parse(t,zn)for t in ['z0*z3-z1**2','z0*z4-z1*z2','z1*z4-z2*z3','z2**2-z1*z3-z0*z3-e*z0**2','z2*z4-z3**2-z1*z3-e*z0*z1']]
for i in range(5):
 ck(pf[i],neg(g[i]),'all five signed Pf=-g');ck(g[i],parse(r['all5_quadrics'][i],zn),'all five quadrics');ck(add(*(mul(Phi[i][j],pf[j])for j in range(5))),{},'Phi*Pf')
O=[[{}for _ in range(5)]for _ in range(5)]
def cyclicterm(a,b,c):
 return add(*(mul(mul(diff(pf[i],a),diff(Phi[i][j],b)),diff(pf[j],c))for i in range(5)for j in range(5)))
for a,b in pairs:
 c,d,f=[j for j in range(5)if j not in(a,b)];p=[a,b,c,d,f];sign=(-1)**sum(p[i]>p[j]for i in range(5)for j in range(i+1,5))
 O[a][b]=scale(add(cyclicterm(c,d,f),cyclicterm(f,c,d),cyclicterm(d,f,c)),sign);O[b][a]=neg(O[a][b]);ck(O[a][b],parse(r['Fisher_Omega_all10_entries'][str((a,b))],zn),'independent cyclic Omega')
M=[[5,-10,10,-5,1],[-4,12,-12,4,0],[4,-4,-4,4,0],[0,-16,16,0,0],[0,16,16,0,0]];Mi=inverse(M)
ck(M,r['actual_GL5_z_from_x'],'actual GL5');ck(determinant(M),Q(16384),'actual GL determinant');ck(Mi,[[Q(a)for a in row]for row in r['GL5_inverse']],'actual inverse')
I=[[Q(i==j)for j in range(5)]for i in range(5)];ck(mm(M,Mi),I,'GL inverse1');ck(mm(Mi,M),I,'GL inverse2')
mx=[add(*(scale(x[j],c)for j,c in enumerate(row)))for row in M]+[x[5]]
Osub=[[subst(v,mx,6)for v in row]for row in O];P=[[add(*(scale(Osub[a][b],Mi[i][a]*Mi[j][b])for a in range(5)for b in range(5)))for j in range(5)]for i in range(5)]
for i,j in pairs:
 ck(P[i][j],parse(r['all10_actual_target_family_brackets'][str((i,j))],xn),'all150 whole e pullback');ck(P[i][j],neg(P[j][i]),'skew')
 assert max((ex[5]for ex in P[i][j]),default=0)<=1
 target=parse(old['all_actual_point_brackets'][str((i,j))],xn)
 ck(specialize(P[i][j]),scale(target,2),'all150 central=2 integer canonical')
for j in range(5):ck(add(*(diff(P[i][j],i)for i in range(5))),{},'all canonical div')
J={}
for tri in triples:
 a,b,c=tri;J[tri]=add(*(mul(P[i][l],diff(P[j][k],l))for i,j,k in [(a,b,c),(b,c,a),(c,a,b)]for l in range(5)));ck(J[tri],{},'full ten strict Jacobi')
for quad in quads:ck(add(*(scale(mul(x[m],J[quad[:i]+quad[i+1:]]),(-1)**i)for i,m in enumerate(quad))),{},'full projective350')
D=add(*(mul(x[i],pf4(P,i))for i in range(5)))
ck(D,parse(r['all126_actual_family_Euler_Pfaffian'],xn),'all126 actual Euler Pf');ck(specialize(D),scale(parse(old['actual_signed_Euler_Pfaffian'],xn),4),'central actual Pf')
detg=subst(pdet([[diff(p,j)for j in range(5)]for p in g]),mx,6)
ck(detg,parse(r['fullfamily_secant_Jacobian'],xn),'full smooth secant determinant');ck(D,scale(detg,Q(-25,32768)),'actual Pf constant secant ratio')
q=[parse(t,xn)for t in ['x0*x2-x1**2','x0*x3-x1*x2','x1*x3-x2**2','x4*x1-x2*x3+x0**2','x4*x2-x3**2+x0*x1']]
A=[[Q(v)for v in row]for row in r['all5_special_quadric_basis_change']];gx=[specialize(subst(p,mx,6))for p in g]
for i in range(5):ck(gx[i],add(*(scale(q[j],A[i][j])for j in range(5))),'all five quadric space maps')
ck(determinant(A),Q(1073741824),'quadric basis determinant')
F=add(mul(x[4],mul(q[0],q[2])),mul(q[2],add(mul(x[2],q[2]),neg(mul(x[3],q[1])))),mul(q[0],add(mul(x[0],q[1]),neg(mul(x[1],q[0])))))
ck(pdet([[diff(p,j)for j in range(5)]for p in q]),scale(F,-2),'special nodal secant determinant')
st=['s','t'];norm=[parse(t,st)for t in ['s**4*t','s**3*t**2','s**2*t**3','s*t**4','t**5-s**5']]+[{}]
for p in q:ck(subst(p,norm,2),{},'whole P1 normalization quadrics')
binary=[subst(p,norm,2)for p in mx[:5]]
for a,b in zip(binary,['(t-s)**5','4*s*t*(t-s)**3','4*s*t*(s+t)*(t-s)**2','16*s**2*t**2*(t-s)','16*s**2*t**2*(s+t)']):ck(a,parse(b,st),'all Weierstrass section identities')
result={'task_id':'E_reduced_nonnormal','all_passed':True,'method':'Independent standard-library Fraction cyclic Fisher/actual GL pullback; no producer or CAS import, no operator/point/jet','all5_model_signed_Pfaffians':True,'full_parameter_polynomial_Omega':True,'all150_actual_pullback_and_central_2canonical':True,'whole_parameter_degree_in_e':1,'all10_strict_and350_projective_Jacobi':True,'all5_divergences':True,'all126_actual_Pf_and_exact_secant_ratio':'-25/32768','GL_det':'16384','quadric_basis_det':'1073741824','whole_normalization_and_Weierstrass_sections':True,'whole_T39_membership_by_smooth_family_closedness':True,'new_component_count':0,'identity_count':N,'input_sha256':{v['path']:v['sha256']for v in job['exact_inputs_and_hashes']},'inline_source':job['inline_source'],'seconds':time.monotonic()-begun,'maximum_RSS_KiB':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss}
out=Path('reports/CLASSIFICATION_CUBIC_CONE_RANK_TWO_NODAL_FISHER_SEPARATE_REVIEW_20261108.json')
with out.open('x')as f:json.dump(result,f,indent=2);f.write('\n')
print(json.dumps({k:result[k]for k in ['all_passed','identity_count','seconds','maximum_RSS_KiB']}))
